public void openNoteEditorForCard(long cardId) {
    mCurrentCardId = cardId;
    sCardBrowserCard = getCol().getCard(mCurrentCardId);
    // start note editor using the card we just loaded
    Intent editCard = new Intent(this, NoteEditor.class);
    editCard.putExtra(NoteEditor.EXTRA_CALLER, NoteEditor.CALLER_CARDBROWSER_EDIT);
    editCard.putExtra(NoteEditor.EXTRA_CARD_ID, sCardBrowserCard.getId());
    startActivityForResultWithAnimation(editCard, EDIT_CARD, ActivityTransitionAnimation.LEFT);
}

/** Opens the note editor for the currently selected note(s) in multi-select mode.
 * Passes all selected note IDs so that note type changes can affect all of them. */
private void openNoteEditorForCurrentlySelectedNote() {
    try {
        long[] selectedCardIds = getSelectedCardIds();
        if (selectedCardIds.length == 0) {
            return;
        }
        // Collect unique note IDs from all selected cards
        HashSet<Long> noteIds = new HashSet<>();
        for (long cardId : selectedCardIds) {
            Card card = getCol().getCard(cardId);
            noteIds.add(card.noteId());
        }
        long[] selectedNoteIds = new long[noteIds.size()];
        int i = 0;
        for (long nid : noteIds) {
            selectedNoteIds[i++] = nid;
        }
        // Open editor for the first card (for preview), but pass all note IDs
        mCurrentCardId = selectedCardIds[0];
        sCardBrowserCard = getCol().getCard(mCurrentCardId);
        Intent editCard = new Intent(this, NoteEditor.class);
        editCard.putExtra(NoteEditor.EXTRA_CALLER, NoteEditor.CALLER_CARDBROWSER_EDIT);
        editCard.putExtra(NoteEditor.EXTRA_CARD_ID, sCardBrowserCard.getId());
        editCard.putExtra(NoteEditor.EXTRA_NOTE_IDS, selectedNoteIds);
        startActivityForResultWithAnimation(editCard, EDIT_CARD, ActivityTransitionAnimation.LEFT);
    } catch (Exception e) {
        Timber.w(e, "Error Opening Note Editor for multi-select");
        UIUtils.showThemedToast(this, getString(R.string.card_browser_note_editor_error), false);
    }
}

